pub(super) fn run_delaunay(points: &[Point]) -> (Vec<Point>, Vec<[usize; 4]>) {
    let mut delaunay = Delaunay3D::new();
    for &p in points {
        delaunay.add_point(p);
    }
    delaunay.tetrahedralize();
    delaunay.extract_mesh()
}

fn adopt_coplanar_facet_patches(
    points: &[Point],
    faces: &HashSet<[usize; 3]>,
    recovered_facets: &mut Vec<RecoveredFacet>,
    operations: &mut RecoveryOperationCounts,
) {
    loop {
        let adoption = coplanar_facet_patch_groups(points, recovered_facets)
            .into_iter()
            .filter(|group| group.len() > 1)
            .find_map(|group| {
                let patch: Vec<_> = group.iter().map(|&index| recovered_facets[index]).collect();
                let result = patch
                    .iter()
                    .any(|facet| !faces.contains(&sorted3(facet.nodes)))
                    .then(|| try_adopt_facet_patch_tiling(points, faces, &patch))
                    .flatten();
                result.map(|adopted| (group, adopted))
            });
        let Some((group, adopted)) = adoption else {
            break;
        };
        let removed: HashSet<_> = group.into_iter().collect();
        *recovered_facets = recovered_facets
            .iter()
            .copied()
            .enumerate()
            .filter_map(|(index, facet)| (!removed.contains(&index)).then_some(facet))
            .collect();
        recovered_facets.extend(adopted);
        operations.facet_tiling_adoptions += 1;
    }
}

pub(super) fn run_constrained_delaunay(
    points: &[Point],
    facets: &[[usize; 3]],
    facet_markers: Option<&[i32]>,
) -> ConstrainedDelaunayRun {
    let fixed_point_count = points.len();
    let mut working_points = points.to_vec();
    let mut recovered_facets: Vec<RecoveredFacet> = facets
        .iter()
        .enumerate()
        .map(|(idx, &nodes)| RecoveredFacet {
            nodes,
            marker: facet_markers.and_then(|m| m.get(idx)).copied().unwrap_or(0),
        })
        .collect();

    // Hard work cap: pathological inputs (coplanar facet partitions with
    // acute junction angles, re-entrant edges) can make Steiner subdivision
    // grow geometrically without converging. Bail out to the degraded path
    // instead of burning unbounded time before the round cap is reached.
    let max_working_points = fixed_point_count.saturating_mul(4).saturating_add(128);
    let mut operations = RecoveryOperationCounts::default();
    let mut rounds = 0;
    let mut termination = ConstraintRecoveryTermination::RoundBudget;

    'recover: for _ in 0..MAX_CONSTRAINT_RECOVERY_ROUNDS {
        rounds += 1;
        if working_points.len() > max_working_points {
            termination = ConstraintRecoveryTermination::SteinerPointBudget;
            break;
        }
        let (nodes, tets) = run_delaunay(&working_points);
        let mut recovery = FlipRecoveryMesh::new(nodes, tets);
        // Recover whole planar patches before edge flips. Their current
        // Delaunay tiling is the evidence being adopted; attempting to force
        // incidental input diagonals first destroys that tiling.
        adopt_coplanar_facet_patches(
            &working_points,
            &recovery.face_set(),
            &mut recovered_facets,
            &mut operations,
        );
        record_flip_counts(
            &mut operations,
            recovery.recover_edges_by_flips(&recovered_facets),
        );
        record_flip_counts(
            &mut operations,
            recovery.recover_facets_by_flips(&recovered_facets),
        );
        operations.non_star_cavity_rejections += recovery.non_star_cavity_rejections;

        let edges = recovery.edge_set();
        let faces = recovery.face_set();

        // A planar surface patch is constrained by its outer and hole
        // boundaries, not by the incidental diagonals used to describe it.
        // Adopt a complete in-situ patch tiling before considering individual
        // facets, whose Delaunay faces may legitimately cross those diagonals.
        adopt_coplanar_facet_patches(
            &working_points,
            &faces,
            &mut recovered_facets,
            &mut operations,
        );

        // A coplanar input facet can already be represented by several
        // Delaunay faces, even when its original boundary edges have been
        // subdivided by the surrounding point set.  Adopt that exact tiling
        // before trying to recover the original edges: splitting first turns
        // each missing edge into more constraints and can create an
        // exponential Steiner cascade on annular caps.  Each adopted face is
        // already a face of the current tetrahedralization, so its edges are
        // present in `edges` on the next round.
        let mut idx = 0;
        while idx < recovered_facets.len() {
            if faces.contains(&sorted3(recovered_facets[idx].nodes)) {
                idx += 1;
                continue;
            }
            if let Some(adopted) =
                try_adopt_facet_tiling(&working_points, &faces, recovered_facets[idx])
            {
                operations.facet_tiling_adoptions += 1;
                recovered_facets.swap_remove(idx);
                recovered_facets.extend(adopted);
            } else {
                idx += 1;
            }
        }

        // Split *every* still-missing constraint edge in one round. Splitting
        // only the lexicographically-first edge starves later edges forever:
        // each midpoint creates new sub-edges that sort ahead of them, so the
        // missing set never drains (observed on annular end-cap partitions).
        let missing_edges: Vec<_> = recovered_constraint_edges_sorted(&recovered_facets)
            .into_iter()
            .filter(|edge| !edges.contains(edge))
            .collect();
        if !missing_edges.is_empty() {
            let tet_edges = recovery.edge_set();
            for edge in missing_edges {
                let splits = constraint_edge_split_points(&working_points, &tet_edges, edge);
                // The cap is a limit on every recovery attempt, not merely
                // on the state at the start of a round.  A pathological PLC
                // can leave many edges unresolved at once; accepting every
                // split here used to overshoot the bound by hundreds of
                // points before the next-round guard ran.
                if splits.len() > max_working_points.saturating_sub(working_points.len()) {
                    termination = ConstraintRecoveryTermination::SteinerPointBudget;
                    break 'recover;
                }
                split_recovered_edge(edge, &splits, &mut working_points, &mut recovered_facets);
                operations.edge_splits += 1;
            }
            continue;
        }

        if let Some(facet_idx) = recovered_facets
            .iter()
            .position(|facet| !faces.contains(&sorted3(facet.nodes)))
        {
            operations.facet_splits += 1;
            let tet_edges = recovery.edge_set();
            let pierce = facet_pierce_point(
                &working_points,
                &tet_edges,
                recovered_facets[facet_idx].nodes,
            );
            split_recovered_facet(
                facet_idx,
                pierce,
                &mut working_points,
                &mut recovered_facets,
            );
            continue;
        }

        if suppress_one_constraint_steiner(
            fixed_point_count,
            &mut working_points,
            &mut recovered_facets,
        ) {
            operations.steiner_suppressions += 1;
            continue;
        }

        let (nodes, tets) = recovery.into_parts();
        let diagnostics = build_recovery_diagnostics(
            facets,
            &recovered_facets,
            &tets,
            RecoveryBuildState {
                rounds,
                steiner_points: working_points.len().saturating_sub(fixed_point_count),
                operations,
                boundary_only: false,
                converged: true,
                termination: ConstraintRecoveryTermination::Recovered,
            },
        );
        return ConstrainedDelaunayRun {
            nodes,
            tets,
            recovered_facets,
            diagnostics,
        };
    }

    // Degraded path: constraint recovery did not converge. Return the best
    // effort mesh — the plain Delaunay tetrahedralization of the (possibly
    // Steiner-augmented) points. The caller receives a structured error and
    // must not treat this mesh as a successful constrained result.
    log::error!(
        "tetrahedralize_surface: constrained boundary recovery did not converge after \
         {MAX_CONSTRAINT_RECOVERY_ROUNDS} rounds ({} input points, {} facets). Known limitation: \
         coplanar facet partitions with acute \
         junction angles (annular end-caps) and re-entrant edges (tube-wall junctions) can \
         defeat the flip-based recovery when the in-plane 2D Delaunay triangulation does not \
         align with the constraint triangulation.",
        fixed_point_count,
        facets.len(),
    );
    let (nodes, tets) = run_delaunay(&working_points);
    let diagnostics = build_recovery_diagnostics(
        facets,
        &recovered_facets,
        &tets,
        RecoveryBuildState {
            rounds,
            steiner_points: working_points.len().saturating_sub(fixed_point_count),
            operations,
            boundary_only: false,
            converged: false,
            termination,
        },
    );
    ConstrainedDelaunayRun {
        nodes,
        tets,
        recovered_facets,
        diagnostics,
    }
}
